L22_1 = {}
L22_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@15#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 707
L22_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L22_1.m_Pos = "C"
L22_1.m_Talk_KOREA = "역시, 시간을 되풀이하는 조건은 당신의 죽음이었던 거야."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "やっぱり、時を繰り返す条件は君の死だったんだ。"
L22_1.m_Talk_ENG = "Just as I thought, the condition for repeating time was your death."
L22_1.m_Talk_TWN = "果然，時間反覆循環的條件就是你的死亡。"
L22_1.m_Talk_DEU = "Just as I thought, the condition for repeating time was your death."
L22_1.m_Talk_FRA = "Just as I thought, the condition for repeating time was your death."
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@16#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 707
L23_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_DESPAIR"
L23_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "...맞아요. 낙원의 운명은 저와 하나로 묶여있어서, 시작과 끝을 함께하거든요."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "……そうです。楽園の運命は私と一つになっていて、始まりと終わりを共有しているのです。"
L23_1.m_Talk_ENG = "...That's right. The fate of the Promised Land is bound together with mine, so it begins and ends with me."
L23_1.m_Talk_TWN = "……沒錯。樂園的命運和我綁在一起，開始與結束都會同時發生。"
L23_1.m_Talk_DEU = "...That's right. The fate of the Promised Land is bound together with mine, so it begins and ends with me."
L23_1.m_Talk_FRA = "...That's right. The fate of the Promised Land is bound together with mine, so it begins and ends with me."
L24_1 = {}
L24_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@17#Talk"
L24_1.m_CutScenProcessKey = 24
L24_1.m_CutScenID = 707
L24_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L24_1.m_bWaitClick = true
L24_1.m_fWaitTime = 0
L24_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L24_1.m_Pos = "C"
L24_1.m_Talk_KOREA = "낙원은 제가 살아있길 바라기 때문에, 매일 죽음을 반복하며 종말을 피할 수 있는 거죠."
L24_1.m_fTalkTime = 0.03
L24_1.m_Talk_JPN = "楽園は私に生きていてほしいため、毎日死を繰り返すことで終末から逃れることができます。"
L24_1.m_Talk_ENG = "Because the Promised Land wishes for me to remain alive, I repeat my death every day to avoid its end."
L24_1.m_Talk_TWN = "因為樂園希望我活著，所以只要我每天重複死亡，就能避開末日。"
L24_1.m_Talk_DEU = "Because the Promised Land wishes for me to remain alive, I repeat my death every day to avoid its end."
L24_1.m_Talk_FRA = "Because the Promised Land wishes for me to remain alive, I repeat my death every day to avoid its end."
