L25_1.m_Pos = "C"
L25_1.m_Talk_KOREA = "창조주가 살아있으면 멸망하고 마는 세계라니. 참 기구한 아이러니네."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "創造主が生きていると滅ぶ世界だなんて、皮肉だね。"
L25_1.m_Talk_ENG = "A world that collapses if its creator stays alive. What a strange irony."
L25_1.m_Talk_TWN = "只要創造者活著，世界反而會毀滅……真諷刺。"
L25_1.m_Talk_DEU = "A world that collapses if its creator stays alive. What a strange irony."
L25_1.m_Talk_FRA = "A world that collapses if its creator stays alive. What a strange irony."
