L28_1.m_Talk_DEU = "That beam of light... what is it?"
L28_1.m_Talk_FRA = "That beam of light... what is it?"
L29_1 = {}
L29_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@21#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 707
L29_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L29_1.m_bWaitClick = true
L29_1.m_fWaitTime = 0
L29_1.m_Face = "UNIT_DESPAIR"
L29_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L29_1.m_Pos = "R"
L29_1.m_bCharPinup = true
L29_1.m_bCharPinupEasingTime = 0.3
L29_1.m_Talk_KOREA = "<color=#ffd34c>낙원문</color>이라 불리는 길이에요. 낙원의 안과 밖을 나누는 유일한 경계이기도 하죠."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "<color=#ffd34c>楽園の門</color>と呼ばれる道です。楽園の内と外を区別する、唯一の境界でもあります。"
L29_1.m_Talk_ENG = "It's a path called <color=#ffd34c>Avalon's Gate</color>. It's also the only boundary that separates the inside of the Promised Land from the outside."
L29_1.m_Talk_TWN = "那是被稱為<color=#ffd34c>樂園門</color>的道路，也是分隔樂園內外的唯一界線。"
L29_1.m_Talk_DEU = "It's a path called <color=#ffd34c>Avalon's Gate</color>. It's also the only boundary that separates the inside of the Promised Land from the outside."
L29_1.m_Talk_FRA = "It's a path called <color=#ffd34c>Avalon's Gate</color>. It's also the only boundary that separates the inside of the Promised Land from the outside."
L30_1 = {}
L30_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@22#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 707
L30_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L30_1.m_Pos = "R"
L30_1.m_bCharPinup = true
L30_1.m_Talk_KOREA = "당신이 떠나고 싶다면, 저곳을 통해야만 나갈 수 있어요."
L30_1.m_fTalkTime = 0.03
L30_1.m_Talk_JPN = "あなたがここを離れたいなら、あそこを通るしかありません。"
L30_1.m_Talk_ENG = "If you want to leave, you can only exit through there."
L30_1.m_Talk_TWN = "如果你想離開，就只能從那裡出去。"
L30_1.m_Talk_DEU = "If you want to leave, you can only exit through there."
L30_1.m_Talk_FRA = "If you want to leave, you can only exit through there."
L31_1 = {}
L31_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@23#Talk"
L31_1.m_CutScenProcessKey = 31
L31_1.m_CutScenID = 707
L31_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SERIOUS"
L31_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L31_1.m_Pos = "L"
L31_1.m_bCharPinup = true
L31_1.m_Talk_KOREA = "...그렇다면 난 떠나겠어."
L31_1.m_fTalkTime = 0.03
L31_1.m_Talk_JPN = "……じゃあ私は行くよ。"
L31_1.m_Talk_ENG = "...Then I'll leave."
L31_1.m_Talk_TWN = "……那我要離開。"
L31_1.m_Talk_DEU = "...Then I'll leave."
L31_1.m_Talk_FRA = "...Then I'll leave."
L32_1 = {}
L32_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@24#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 707
L32_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L32_1.m_Pos = "L"
L32_1.m_bCharPinup = true
L32_1.m_Talk_KOREA = "너도, 매일 죽는 고통을 느낄 바엔 순순히 현실을 받아들이고 떠나는 게 어때?"
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "君も、毎日死の苦しみを味わうくらいなら、大人しく現実を受け入れてここを離れたらどう？"
L32_1.m_Talk_ENG = "Rather than suffering through dying every day, how about you accept reality and leave as well?"
L32_1.m_Talk_TWN = "你也是。與其每天承受死亡的痛苦，不如乾脆接受現實離開怎麼樣？"
L32_1.m_Talk_DEU = "Rather than suffering through dying every day, how about you accept reality and leave as well?"
L32_1.m_Talk_FRA = "Rather than suffering through dying every day, how about you accept reality and leave as well?"
L33_1 = {}
L33_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@25#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 707
L33_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_Face = "UNIT_IDLE"
L33_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L33_1.m_Pos = "R"
L33_1.m_bCharPinup = true
L33_1.m_Talk_KOREA = "그럴 순 없어요."
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "そうはいきません。"
L33_1.m_Talk_ENG = "I can't do that."
L33_1.m_Talk_TWN = "不行。"
L33_1.m_Talk_DEU = "I can't do that."
L33_1.m_Talk_FRA = "I can't do that."
L34_1 = {}
L34_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@26#Talk"
L34_1.m_CutScenProcessKey = 34
L34_1.m_CutScenID = 707
L34_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L34_1.m_Pos = "R"
L34_1.m_bCharPinup = true
L34_1.m_Talk_KOREA = "전 문턱을 넘는 것만으론 헤어날 수 없을 만큼, 이미 너무 깊이 들어와 버린 걸요."
L34_1.m_fTalkTime = 0.03
L34_1.m_Talk_JPN = "すでに扉をくぐるだけでは逃れられないほど、深く関わってしまっていますから。"
L34_1.m_Talk_ENG = "I've already gone too deep to escape just by crossing the threshold."
L34_1.m_Talk_TWN = "我已經深入到光是跨過門也無法脫身的程度了。"
L34_1.m_Talk_DEU = "I've already gone too deep to escape just by crossing the threshold."
L34_1.m_Talk_FRA = "I've already gone too deep to escape just by crossing the threshold."
L35_1 = {}
L35_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@27#Talk"
L35_1.m_CutScenProcessKey = 35
L35_1.m_CutScenID = 707
L35_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L35_1.m_Pos = "L"
L35_1.m_bCharPinup = true
L35_1.m_Talk_KOREA = "우리 세계를 네 낙원의 양분으로 만들 거라고 했지?"
L35_1.m_fTalkTime = 0.03
L35_1.m_Talk_JPN = "私たちの世界を、楽園の養分にするって言ったよね。"
L35_1.m_Talk_ENG = "You said you were going to make our world into nutrients for your paradise, didn't you?"
L35_1.m_Talk_TWN = "你說過要把我們的世界變成你樂園的養分。"
L35_1.m_Talk_DEU = "You said you were going to make our world into nutrients for your paradise, didn't you?"
L35_1.m_Talk_FRA = "You said you were going to make our world into nutrients for your paradise, didn't you?"
L36_1 = {}
L36_1.m_CutScenKey_Talk = "EP15_ACT3_INTERLUDE13@28#Talk"
L36_1.m_CutScenProcessKey = 36
L36_1.m_CutScenID = 707
L36_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L36_1.m_bWaitClick = true
L36_1.m_fWaitTime = 0
L36_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L36_1.m_Pos = "L"
L36_1.m_bCharPinup = true
L36_1.m_Talk_KOREA = "타기리온은 실패할 거야. 그러니 네가 바라는 낙원이 완성될 일도 없을 테고."
L36_1.m_fTalkTime = 0.03
L36_1.m_Talk_JPN = "タギリオンは失敗するよ。だから君が望む楽園が完成することはない。"
L36_1.m_Talk_ENG = "Thagirion will fail. So the paradise you're hoping for will never be completed."
L36_1.m_Talk_TWN = "塔基里翁會失敗的，所以你期望的樂園也不會完成。"
L36_1.m_Talk_DEU = "Thagirion will fail. So the paradise you're hoping for will never be completed."
L36_1.m_Talk_FRA = "Thagirion will fail. So the paradise you're hoping for will never be completed."
L37_1 = {}
