L37_1.m_Talk_KOREA = "반드시 성공할 필요는 없어요."
L37_1.m_fTalkTime = 0.03
L37_1.m_Talk_JPN = "必ずしも成功する必要はありません。"
L37_1.m_Talk_ENG = "It doesn't need to succeed."
L37_1.m_Talk_TWN = "不一定要成功。"
L37_1.m_Talk_DEU = "It doesn't need to succeed."
L37_1.m_Talk_FRA = "It doesn't need to succeed."
