L30_1.m_Talk_JPN = L31_1
L31_1 = "W-we should take her with us quickly! It's a bit far to the Order, but once we get there, the doctors will help her!"
L30_1.m_Talk_ENG = L31_1
L31_1 = "快、快帶她走吧！雖然到教團有點遠，但到了那邊醫生一定會幫忙！"
L30_1.m_Talk_TWN = L31_1
L31_1 = "W-we should take her with us quickly! It's a bit far to the Order, but once we get there, the doctors will help her!"
