L1_1.m_bCharPinup = true
L2_1 = "너의 누이를 찾는 것처럼, 우린 그저 산 자들의 구원을 위해 노력할 뿐."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "そなたの姉を探すように、我らはただ生きている者を救うため努力するだけなのだ。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "Just as you search for your sister, we merely strive for the salvation of the living."
L1_1.m_Talk_ENG = L2_1
L2_1 = "就像你尋找你姐姐一樣，我們只能努力拯救還活著的人。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "Just as you search for your sister, we merely strive for the salvation of the living."
L1_1.m_Talk_DEU = L2_1
L2_1 = "Just as you search for your sister, we merely strive for the salvation of the living."
L1_1.m_Talk_FRA = L2_1
