L2_1.m_Pos = "R"
L2_1.m_bCharPinup = true
L3_1 = "그러네요. 산 사람은 산 사람을 위해서... 좌절에 빠져있으면 안되는 거겠죠."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "そうですね。生きている人のために……落ちこんでいてはいけませんね。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "You're right. The living must fight for the living... There's no need to be in despair."
L2_1.m_Talk_ENG = L3_1
L3_1 = "說得也是。活著的人，必須為活著的人努力……不能沉溺在絕望中。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "You're right. The living must fight for the living... There's no need to be in despair."
L2_1.m_Talk_DEU = L3_1
L3_1 = "You're right. The living must fight for the living... There's no need to be in despair."
L2_1.m_Talk_FRA = L3_1
