L10_1 = "MORS_SHADOW_ARMOR_NULL"
L9_1.m_CharStrID = L10_1
L9_1.m_Pos = "C"
L10_1 = "고통을 필요로 하지 않는 그곳에서, 네가 가진 본래 기억들은 무가치한 것이었다."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "苦痛を必要としないそこでは、そなたの持つ本来の記憶は無価値なものであった。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "In that place, which has no need for suffering, your original memories held no value."
L9_1.m_Talk_ENG = L10_1
L10_1 = "在那個不需要痛苦的地方，你原本的記憶沒有任何價值。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "In that place, which has no need for suffering, your original memories held no value."
L9_1.m_Talk_DEU = L10_1
L10_1 = "In that place, which has no need for suffering, your original memories held no value."
L9_1.m_Talk_FRA = L10_1
