L11_1 = "EP15_ACT3_INTERLUDE13@108#Talk"
L10_1.m_CutScenKey_Talk = L11_1
L11_1 = 160
L10_1.m_CutScenProcessKey = L11_1
L10_1.m_CutScenID = 707
L10_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L10_1.m_bWaitClick = true
L10_1.m_fWaitTime = 0
L11_1 = "MORS_SHADOW_ARMOR_NULL"
L10_1.m_CharStrID = L11_1
L10_1.m_Pos = "C"
L11_1 = "그래서 낙원은 네 대부분의 기억을 지웠고, 과거의 행복했던 시절만을 남겼지."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "ゆえに楽園はそなたのほとんどの記憶を抹消し、幸福であった頃の記憶のみを残した。"
L10_1.m_Talk_JPN = L11_1
L11_1 = "So the Promised Land erased most of your memories and left behind only the happy days of your past."
L10_1.m_Talk_ENG = L11_1
L11_1 = "因此樂園抹去了你大部分的記憶，只留下過去那些幸福的時光。"
L10_1.m_Talk_TWN = L11_1
L11_1 = "So the Promised Land erased most of your memories and left behind only the happy days of your past."
L10_1.m_Talk_DEU = L11_1
L11_1 = "So the Promised Land erased most of your memories and left behind only the happy days of your past."
L10_1.m_Talk_FRA = L11_1
L11_1 = {}
L12_1 = "EP15_ACT3_INTERLUDE13@109#Talk"
L11_1.m_CutScenKey_Talk = L12_1
L12_1 = 161
L11_1.m_CutScenProcessKey = L12_1
L11_1.m_CutScenID = 707
L11_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "MORS_SHADOW_ARMOR_NULL"
L11_1.m_CharStrID = L12_1
L11_1.m_Pos = "C"
L12_1 = "겨울의 역병으로 죽어가는 인간조차 한 번 본 적이 없는, 순수하고 무지한 시절로 돌아간 거다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "冬の疫病で死にゆく人間すら一度も目にしたことのない、純粋かつ無知な頃に戻ったのだ。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "You returned to a pure and ignorant time, one that had never even seen humans dying from the winter plague."
L11_1.m_Talk_ENG = L12_1
L12_1 = "讓你回到那個連冬天瘟疫奪走生命的景象都未曾見過、純粹而無知的時候。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "You returned to a pure and ignorant time, one that had never even seen humans dying from the winter plague."
L11_1.m_Talk_DEU = L12_1
L12_1 = "You returned to a pure and ignorant time, one that had never even seen humans dying from the winter plague."
L11_1.m_Talk_FRA = L12_1
