L15_1 = "MORS_SHADOW_NPC_GIRL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C"
L15_1 = "그 이름을 얻고, 마왕 타기리온을 쫓아 영겁을 떠돌며, 좌절 끝에 다다른 곳엔..."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "その名を手に入れ、魔王タギリオンを追って永劫をさまよい、挫折の果てにたどり着いた場所には……"
L14_1.m_Talk_JPN = L15_1
L15_1 = "After receiving that name, I wandered for eternity in pursuit of Demon Lord Thagirion, and at the end of my despair..."
L14_1.m_Talk_ENG = L15_1
L15_1 = "得到那個名字後，你追逐魔王塔基里翁，在漫長歲月中漂泊。"
L14_1.m_Talk_TWN = L15_1
