L43_1.m_CharStrID = L44_1
L43_1.m_Pos = "L"
L44_1 = "이 녀석은 항상 자신의 구동 한계를 간과하고 몸을 험하게 움직이거든. 이번에도 그렇고."
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "こいつはいつも自分の稼働限界を顧みず体を酷使する。今回もそうだ。"
L43_1.m_Talk_JPN = L44_1
L44_1 = "This one always ignores its operating limits and pushes its body too hard. Just like this time."
L43_1.m_Talk_ENG = L44_1
L44_1 = "這傢伙老是無視自己的動作極限亂動身體，這次也一樣。"
