L45_1 = "KEEPER_ANAP_NULL_NONAME"
L44_1.m_CharStrID = L45_1
L44_1.m_Pos = "R"
L45_1 = "간과한 게 아니라, 긴급한 상황에 필요한 판단을 했을 뿐입니다. 모함꾼."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "顧みなかったわけではなく、緊急時に必要な判断をしたまでです。ホラ吹き。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "I didn't ignore them. I simply made the judgment required for an urgent situation, slanderer."
L44_1.m_Talk_ENG = L45_1
L45_1 = "我不是無視，而是在緊急情況下做出必要判斷。少批評我。"
