L48_1.m_Pos = "C"
L48_1.m_bCharPinup = true
L49_1 = "낙원의 하루가 되풀이되고 나면, 모든 게 다 원래대로 돌아오는 게 아니었나?"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "楽園の一日が繰り返されれば、すべてが元通りになるんじゃなかったの？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Once the day in the Promised Land repeats, doesn't everything return to how it was before?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "不是只要重置樂園的一天，一切都會回到原樣嗎？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "Once the day in the Promised Land repeats, doesn't everything return to how it was before?"
L48_1.m_Talk_DEU = L49_1
