L50_1 = "이 녀석은 예외다. 낙원의 주민이 아니거든."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "こいつは例外だ。楽園の住民じゃないからな。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "This one is an exception. She isn't a resident."
L49_1.m_Talk_ENG = L50_1
L50_1 = "這傢伙是例外，它不是樂園的居民。"
