L50_1.m_CharStrID = L51_1
L50_1.m_Pos = "L"
L51_1 = "낙원이 만들어지기도 전... 그러니까 아우드라가 어둠 속에서 혼자였을 적에 심심해서 만든 인형이야."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "楽園が作られる前……つまり、アウドラが闇の中で独りだった頃、退屈しのぎで作った人形だ。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "It's a doll Audra made before the Promised Land even existed... Back when she was alone in the darkness and bored."
