L2_1 = "하, 심심해서 만든 인형이 침식체를 종잇장처럼 찢어발긴다고?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "は、退屈しのぎで作られた人形が侵食体を八つ裂きにする？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "*Sigh* A doll she made out of boredom tears C.O.s apart like they're nothing?"
L1_1.m_Talk_ENG = L2_1
L2_1 = "啊？無聊做出來的人偶，卻能把侵蝕體像紙張一樣撕碎？"
