L31_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L31_1.m_Pos = "L"
L31_1.m_bCharPinup = true
L32_1 = "내가 명령만 수행하는 기계를 만들었다면, 감정대로 성질 부리고 대꾸하는 기능 같은 건 만들지 않았을 텐데 말이야."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "もし私が命令を遂行するためだけの機械を作るんなら、感情的に怒ったり、口答えする機能は入れなかったと思うな。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "If I were the one who made a machine that only follows orders, I wouldn't have given it the ability to act on its emotions and talk back."
L31_1.m_Talk_ENG = L32_1
L32_1 = "如果我要做一個只會聽我命令的機械，不會設計這種會發脾氣還會回嘴的功能。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "If I were the one who made a machine that only follows orders, I wouldn't have given it the ability to act on its emotions and talk back."
L31_1.m_Talk_DEU = L32_1
L32_1 = "If I were the one who made a machine that only follows orders, I wouldn't have given it the ability to act on its emotions and talk back."
