L40_1.m_Pos = "C"
L41_1 = "아핫, 보답으로 뭘 원하냐고? 재밌는 인형이네."
L40_1.m_Talk_KOREA = L41_1
L40_1.m_fTalkTime = 0.03
L41_1 = "あはっ、見返りとして何を求めるのかって？　面白い人形だね。"
