L44_1.m_Pos = "C"
L45_1 = "응. 친구는 필요할 때 서로 돕는 거야. 거기엔 아무 보답도 필요없어. 돕는 것만으로도 마음이 기뻐지거든."
L44_1.m_Talk_KOREA = L45_1
L44_1.m_fTalkTime = 0.03
L45_1 = "うん。友だちは必要な時に助け合うものなの。そこには何の見返りも要らない。助けるだけで嬉しくなるの。"
L44_1.m_Talk_JPN = L45_1
L45_1 = "Yes. Friends help each other when they need to. There's no need for repayment. Helping alone makes your heart happy."
L44_1.m_Talk_ENG = L45_1
L45_1 = "嗯。朋友就是在需要時互相幫助。不需要回報，光幫助對方就會感到開心。"
L44_1.m_Talk_TWN = L45_1
L45_1 = "Yes. Friends help each other when they need to. There's no need for repayment. Helping alone makes your heart happy."
L44_1.m_Talk_DEU = L45_1
L45_1 = "Yes. Friends help each other when they need to. There's no need for repayment. Helping alone makes your heart happy."
