L46_1 = "친구를 돕는 데 필요한 건, 마음 하나로 충분하니까."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "必要なものは、気持ちだけで十分。"
