L46_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L46_1.m_Pos = "C"
L47_1 = "이 낙원을 지키는 건, 날 지키는 것보다 더 중요한 일이야."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "この楽園を守ることは、私を守ることより大事なことだよ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Protecting the Promised Land is more important than protecting me."
L46_1.m_Talk_ENG = L47_1
L47_1 = "守護這個樂園，比守護我自己更重要。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "Protecting the Promised Land is more important than protecting me."
