L49_1 = "KEEPER_ANAP_NULL_NONAME"
L48_1.m_CharStrID = L49_1
L49_1 = "지켜야 할 낙원이란 것에 대한... 정의가 필요합니다."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "守るべき楽園というものに対する……定義が必要です。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I need a definition... of what this Promised Land I must protect is."
L48_1.m_Talk_ENG = L49_1
L49_1 = "那麼，必須先定義……什麼是需要守護的樂園。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "I need a definition... of what this Promised Land I must protect is."
