L49_1.m_CutScenKey_Talk = L50_1
L50_1 = 249
L49_1.m_CutScenProcessKey = L50_1
L49_1.m_CutScenID = 707
L49_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
