L50_1 = "UNIT_LAUGH"
L49_1.m_Face = L50_1
L49_1.m_CharStrID = "DASH_ANAP_CA_NULL"
L49_1.m_Pos = "C"
L50_1 = "낙원이란 건, 모두가 편안히 쉴 수 있는 마음의 안식처. 그곳의 평화를 지키기 위해서라면, 난 무엇이든 할 각오가 되어있어."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "楽園はみんなが穏やかに過ごせる心の拠り所。その平和を守るためなら、私は何でもする覚悟ができている。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "The Promised Land is a place where everyone can rest peacefully in their hearts. If it's to protect the peace of that place, I'm prepared to do anything."
L49_1.m_Talk_ENG = L50_1
L50_1 = "樂園就是所有人能安心休息的心靈棲所。為了守護那裡的和平，我願意做任何事。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "The Promised Land is a place where everyone can rest peacefully in their hearts. If it's to protect the peace of that place, I'm prepared to do anything."
L49_1.m_Talk_DEU = L50_1
L50_1 = "The Promised Land is a place where everyone can rest peacefully in their hearts. If it's to protect the peace of that place, I'm prepared to do anything."
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
