L50_1.m_CutScenKey_Talk = L51_1
L51_1 = 250
L50_1.m_CutScenProcessKey = L51_1
L50_1.m_CutScenID = 707
L50_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
