L50_1.m_Pos = "C"
L51_1 = "하지만 낙원은 완전하지 않아서, 아직 겨울이 와서는 안 돼. 밤이 되기 전에 내가 죽어야만 다시 가을 끝무렵의 아침을 되풀이할 수 있지."
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "でも楽園は完全じゃないから、まだ冬が来てはいけない。晩秋の朝を繰り返すためには、夜になる前に私が死ぬ必要があるの。"
L50_1.m_Talk_JPN = L51_1
L51_1 = "But the Promised Land isn't complete yet, so winter must not come. Before night falls, I have to die so the morning at the end of autumn can repeat again."
L50_1.m_Talk_ENG = L51_1
L51_1 = "但樂園還不完整，所以冬天不能到來。在夜晚降臨前我必須死去，才能讓時間重新回到秋末的清晨。"
L50_1.m_Talk_TWN = L51_1
L51_1 = "But the Promised Land isn't complete yet, so winter must not come. Before night falls, I have to die so the morning at the end of autumn can repeat again."
L50_1.m_Talk_DEU = L51_1
L51_1 = "But the Promised Land isn't complete yet, so winter must not come. Before night falls, I have to die so the morning at the end of autumn can repeat again."
L50_1.m_Talk_FRA = L51_1
