L6_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L6_1.m_Pos = "L"
L6_1.m_bCharPinup = true
L7_1 = "곤경에 처한 남을 도왔을 때 만족하게 되는 게 보통의 사람 심리거든. 도와준 상대가 친구라면 더 만족스러울 테고."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "困った人を助けた時に満足感を覚えるのが、普通の人の心理だから。相手が友だちならなおのこと。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "It's only natural for people to feel satisfied when they help someone in trouble. If the person they helped is a friend, they'd feel even more satisfied."
L6_1.m_Talk_ENG = L7_1
L7_1 = "幫助陷入困境的人時，人通常會感到滿足。如果對方是朋友，滿足感會更強。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "It's only natural for people to feel satisfied when they help someone in trouble. If the person they helped is a friend, they'd feel even more satisfied."
L6_1.m_Talk_DEU = L7_1
L7_1 = "It's only natural for people to feel satisfied when they help someone in trouble. If the person they helped is a friend, they'd feel even more satisfied."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP15_ACT3_INTERLUDE13@185#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 257
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 707
L7_1.m_CutScenStrID = "EP15_ACT3_INTERLUDE13"
