L7_1.m_Face = "UNIT_IDLE"
L8_1 = "KEEPER_ANAP_NULL_NONAME"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "R"
L8_1 = "그럼. 친구의 부탁을 들어줘도 기쁘지 않다면... 보통의 사람은 어떻게 합니까?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "では、その友だちの頼み事を叶えてあげても嬉しくならない場合……普通の人間はどうしますか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Then... if helping that friend's request does not make them happy, what would an ordinary person do?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "那如果幫助朋友的請求，卻一點也不快樂……一般人會怎麼做？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "Then... if helping that friend's request does not make them happy, what would an ordinary person do?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Then... if helping that friend's request does not make them happy, what would an ordinary person do?"
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
L9_1 = "EP15_ACT3_INTERLUDE13@186#Talk"
