L10_1 = "EP15_ACT3_INTERLUDE13@187#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 259
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 707
