L9_1.m_CharStrID = "AGENT_GRONIA_WHITE_NAME"
L9_1.m_Pos = "L"
L9_1.m_bCharPinup = true
L10_1 = "기쁘지 않은 일을 억지로 하게 된다면, 적어도 그건 널 위한 일은 아닐 테니까."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "嬉しくないことを嫌々するなら、少なくともそれは君のためにならないはずだし。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "If you force yourself to do something that does not make you happy, then at the very least, it's not something you're doing for yourself."
L9_1.m_Talk_ENG = L10_1
L10_1 = "如果被迫做不開心的事，至少那不是為了你自己。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "If you force yourself to do something that does not make you happy, then at the very least, it's not something you're doing for yourself."
L9_1.m_Talk_DEU = L10_1
L10_1 = "If you force yourself to do something that does not make you happy, then at the very least, it's not something you're doing for yourself."
L9_1.m_Talk_FRA = L10_1
