L11_1 = "이렇게 아무 잘못 없는 사람을 가둬놓는 거, 너도 썩 유쾌한 기분은 아니잖아? 네 마음은 어때?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "今みたいに罪のない人を監禁するのは、いい気がしないんじゃない？　君の気持ちはどう？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Locking up someone who's done nothing wrong like this, you don't feel very good about it either, do you? How do you feel?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "像這樣把一個無辜的人關起來，你心裡也不會舒服吧？你怎麼想？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "Locking up someone who's done nothing wrong like this, you don't feel very good about it either, do you? How do you feel?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Locking up someone who's done nothing wrong like this, you don't feel very good about it either, do you? How do you feel?"
L10_1.m_Talk_FRA = L11_1
