L12_1.m_fTalkTime = 0.03
L13_1 = "あなたがここから出れば更に大きな問題を起こすでしょうし、私はあなたを傷つけてでもそれを止めることになるでしょう。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "If you leave here, you will cause even greater trouble, and I'll stop that even if it means harming you."
L12_1.m_Talk_ENG = L13_1
L13_1 = "如果你離開這裡，只會造成更大的問題。就算必須傷害你，我也會阻止。"
