L20_1.m_CharStrID = L21_1
L20_1.m_Pos = "C"
L21_1 = "영원히 멈춰두었던 세계에 시간이 흐르면서 생겨난 작은 파문..."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "永遠に止まっていた世界に時間が流れ始めたことで生まれた小さな波紋……"
L20_1.m_Talk_JPN = L21_1
L21_1 = "A small ripple formed as time began to flow once more in a world that had been stopped forever..."
L20_1.m_Talk_ENG = L21_1
L21_1 = "時間在原本永遠停滯的世界開始流動，產生了一點小小的漣漪。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "A small ripple formed as time began to flow once more in a world that had been stopped forever..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "A small ripple formed as time began to flow once more in a world that had been stopped forever..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
