L21_1.m_Pos = "C"
L22_1 = "그리고, 그 작은 파문 때문에 많은 변화가 일어날 거야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "その小さな波紋のせいで、多くの変化が起こるの。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "And because of that small ripple, many changes will begin to occur."
L21_1.m_Talk_ENG = L22_1
L22_1 = "而那小小的漣漪，會帶來很多變化。"
