L24_1.m_fTalkTime = 0.03
L25_1 = "まず、時間の境界を彷徨っていたオオカミの群れが、ここに繋がる道を探し出すでしょう。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "First, the pack of wolves that had been wandering along the boundary of time will find their way here."
L24_1.m_Talk_ENG = L25_1
L25_1 = "首先，在時間邊界徘徊的狼群，會找到通往這裡的路。"
