L33_1 = "내가 그 아일 어떻게 할진, 내 운명에 달려있어."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "私が彼女をどうするかは、私の運命次第ね。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "What I will do with her depends on my fate."
L32_1.m_Talk_ENG = L33_1
L33_1 = "我會怎麼對她，取決於我的命運。"
